package com.sourcetoolkit.app;
import android.app.*;import android.os.Bundle;import android.net.Uri;import android.widget.*;import androidx.documentfile.provider.DocumentFile;
public class ModFolderActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xFF0B0E10);getWindow().setNavigationBarColor(0xFF0B0E10);DocumentFile f=DocumentFile.fromTreeUri(this,Uri.parse(getIntent().getStringExtra("uri")));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,18,18,12);root.setBackgroundColor(0xFF0B0E10);setContentView(root);TextView h=new TextView(this);h.setText(f.getName());h.setTextSize(20);h.setTextColor(0xFFE6EAED);root.addView(h);ScrollView sc=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);root.addView(sc);for(DocumentFile x:f.listFiles()){TextView t=new TextView(this);t.setText((x.isDirectory()?"▸ ":"")+x.getName());t.setTextColor(0xFFE6EAED);t.setPadding(8,14,8,14);list.addView(t);t.setOnClickListener(v->{if(x.isDirectory()){Intent i=new Intent(this,ModFolderActivity.class);i.putExtra("uri",x.getUri().toString());startActivity(i);}else Toast.makeText(this,x.getName(),0).show();});}}
}